<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$q=trim($_GET['q']??'');$difficulty=$_GET['difficulty']??'';$params=[];$sql='SELECT p.*,COUNT(DISTINCT ps.skill_id) skill_count FROM projects p LEFT JOIN project_skills ps ON ps.project_id=p.project_id WHERE p.is_active=1';if($q!==''){$sql.=' AND (p.title LIKE ? OR p.description LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if(in_array($difficulty,['beginner','intermediate','advanced'],true)){$sql.=' AND p.difficulty=?';$params[]=$difficulty;}$sql.=' GROUP BY p.project_id ORDER BY FIELD(p.difficulty,\'beginner\',\'intermediate\',\'advanced\'),p.title';$st=$pdo->prepare($sql);$st->execute($params);$projects=$st->fetchAll();$pageTitle='Project library';$active='projects';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="page-head"><div><span class="eyebrow">Learn by building</span><h1 class="h1">Practical project library</h1><p>Explore hands-on project ideas connected to the skills used in different career paths.</p></div></div><form class="filters" method="get"><div class="search-box"><span>⌕</span><input name="q" value="<?=h($q)?>" placeholder="Search projects…"></div><select class="select" name="difficulty" style="max-width:190px"><option value="">All difficulty levels</option><?php foreach(['beginner','intermediate','advanced'] as $d):?><option value="<?=$d?>" <?=$difficulty===$d?'selected':''?>><?=ucfirst($d)?></option><?php endforeach;?></select><button class="btn btn-primary btn-sm">Filter</button></form><div class="grid grid-3"><?php foreach($projects as $p):?><article class="card project-card"><div class="project-banner"><span class="pill pill-blue"><?=h(ucfirst($p['difficulty']))?></span><span class="project-symbol">◇</span></div><div class="project-body"><h3><?=h($p['title'])?></h3><p><?=h($p['description'])?></p><div class="tag-row"><span class="tag">⌛ <?=h($p['estimated_hours']?:'Flexible')?> hours</span><span class="tag"><?=$p['skill_count']?> skills</span></div><div class="row-between" style="margin-top:17px"><a class="link-arrow" href="<?=h(url('projects/view.php?id='.(int)$p['project_id']))?>">View project →</a><span class="muted tiny">Practical</span></div></div></article><?php endforeach;?></div><?php if(!$projects):?><div class="card empty-state"><h2>No projects match this search</h2><p>Try a different keyword or remove the difficulty filter.</p></div><?php endif;?></div></main><?php include __DIR__.'/../includes/footer.php';?>
